import {
  createContext,
  forwardRef,
  type ButtonHTMLAttributes,
  type HTMLAttributes,
  type MutableRefObject,
  type ReactNode,
  type Ref,
  type RefObject,
  useCallback,
  useContext,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react'
import { createPortal } from 'react-dom'

import { containTabFocus, focusInitialElement } from './dialog/focus'
import { isTopDialogLayer, registerDialogLayer } from './dialog/layers'

type OpenChangeHandler = (open: boolean) => void

export type DialogRootProps = {
  children: ReactNode
  defaultOpen?: boolean
  onOpenChange?: OpenChangeHandler
  open?: boolean
}

export type DialogTriggerProps = ButtonHTMLAttributes<HTMLButtonElement>
export type DialogOverlayProps = HTMLAttributes<HTMLDivElement>
export type DialogTitleProps = Omit<HTMLAttributes<HTMLHeadingElement>, 'id'>
export type DialogDescriptionProps = Omit<HTMLAttributes<HTMLParagraphElement>, 'id'>
export type DialogCloseProps = ButtonHTMLAttributes<HTMLButtonElement>

type DialogContextValue = {
  contentId: string
  descriptionId: string
  descriptionMounted: boolean
  layerId: symbol
  open: boolean
  registerDescription: () => () => void
  registerTitle: () => () => void
  requestOpenChange: OpenChangeHandler
  restoreAnimationFrameRef: MutableRefObject<number | null>
  returnFocusRef: MutableRefObject<HTMLElement | null>
  titleId: string
  titleMounted: boolean
  triggerRef: MutableRefObject<HTMLButtonElement | null>
}

const DialogContext = createContext<DialogContextValue | null>(null)
const useBrowserLayoutEffect = typeof document === 'undefined' ? useEffect : useLayoutEffect

function useDialogContext(componentName: string) {
  const context = useContext(DialogContext)
  if (!context) throw new Error(`${componentName} must be rendered inside Dialog.Root`)
  return context
}

function usePresenceRegistration() {
  const [count, setCount] = useState(0)
  const register = useCallback(() => {
    setCount((current) => current + 1)
    return () => setCount((current) => Math.max(0, current - 1))
  }, [])

  return [count > 0, register] as const
}

function assignRef<T>(ref: Ref<T> | undefined, value: T | null) {
  if (typeof ref === 'function') ref(value)
  else if (ref) ref.current = value
}

function useComposedRefs<T>(...refs: Array<Ref<T> | undefined>) {
  return useCallback((value: T | null) => {
    for (const ref of refs) assignRef(ref, value)
  }, refs)
}

function useLatest<T>(value: T) {
  const ref = useRef(value)
  useBrowserLayoutEffect(() => {
    ref.current = value
  })
  return ref
}

export function DialogRoot({ children, defaultOpen = false, onOpenChange, open }: DialogRootProps) {
  const isControlled = open !== undefined
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen)
  const currentOpen = isControlled ? open : uncontrolledOpen
  const onOpenChangeRef = useLatest(onOpenChange)
  const [titleMounted, registerTitle] = usePresenceRegistration()
  const [descriptionMounted, registerDescription] = usePresenceRegistration()
  const generatedId = useId()
  const triggerRef = useRef<HTMLButtonElement | null>(null)
  const returnFocusRef = useRef<HTMLElement | null>(null)
  const restoreAnimationFrameRef = useRef<number | null>(null)
  const layerId = useRef(Symbol('dialog-layer')).current

  const requestOpenChange = useCallback<OpenChangeHandler>((nextOpen) => {
    if (!isControlled) setUncontrolledOpen(nextOpen)
    if (nextOpen !== currentOpen) onOpenChangeRef.current?.(nextOpen)
  }, [currentOpen, isControlled, onOpenChangeRef])

  const context = useMemo<DialogContextValue>(() => ({
    contentId: `${generatedId}-content`,
    descriptionId: `${generatedId}-description`,
    descriptionMounted,
    layerId,
    open: currentOpen,
    registerDescription,
    registerTitle,
    requestOpenChange,
    restoreAnimationFrameRef,
    returnFocusRef,
    titleId: `${generatedId}-title`,
    titleMounted,
    triggerRef,
  }), [
    currentOpen,
    descriptionMounted,
    generatedId,
    layerId,
    registerDescription,
    registerTitle,
    requestOpenChange,
    titleMounted,
  ])

  return <DialogContext.Provider value={context}>{children}</DialogContext.Provider>
}

export const DialogTrigger = forwardRef<HTMLButtonElement, DialogTriggerProps>(
  function DialogTrigger({ onClick, type = 'button', ...props }, forwardedRef) {
    const context = useDialogContext('Dialog.Trigger')
    const ref = useComposedRefs(forwardedRef, context.triggerRef)

    return (
      <button
        {...props}
        aria-controls={context.contentId}
        aria-expanded={context.open}
        aria-haspopup="dialog"
        data-state={context.open ? 'open' : 'closed'}
        onClick={(event) => {
          onClick?.(event)
          if (event.defaultPrevented) return
          context.returnFocusRef.current = event.currentTarget
          context.requestOpenChange(true)
        }}
        ref={ref}
        type={type}
      />
    )
  },
)

export type DialogPortalProps = {
  children: ReactNode
  container?: Element | DocumentFragment | null
}

export function DialogPortal({ children, container }: DialogPortalProps) {
  const context = useDialogContext('Dialog.Portal')
  const [hydrated, setHydrated] = useState(false)

  useBrowserLayoutEffect(() => setHydrated(true), [])

  if (!context.open || !hydrated) return null
  const target = container === undefined ? document.body : container
  if (!target) return null

  return createPortal(<div data-dialog-portal="">{children}</div>, target)
}

export const DialogOverlay = forwardRef<HTMLDivElement, DialogOverlayProps>(
  function DialogOverlay({ onClick, onPointerDown, ...props }, forwardedRef) {
    const context = useDialogContext('Dialog.Overlay')
    const pointerStartedOutsideRef = useRef(false)

    return (
      <div
        {...props}
        data-state={context.open ? 'open' : 'closed'}
        onClick={(event) => {
          onClick?.(event)
          const shouldDismiss = pointerStartedOutsideRef.current && !event.defaultPrevented
          pointerStartedOutsideRef.current = false
          if (shouldDismiss) context.requestOpenChange(false)
        }}
        onPointerDown={(event) => {
          onPointerDown?.(event)
          pointerStartedOutsideRef.current = !event.defaultPrevented &&
            event.button === 0 &&
            event.target === event.currentTarget &&
            isTopDialogLayer(event.currentTarget.ownerDocument, context.layerId)
        }}
        ref={forwardedRef}
      />
    )
  },
)

export type DialogContentProps = Omit<HTMLAttributes<HTMLDivElement>, 'id' | 'role'> & {
  initialFocusRef?: RefObject<HTMLElement | null>
  onEscapeKeyDown?: (event: KeyboardEvent) => void
}

export const DialogContent = forwardRef<HTMLDivElement, DialogContentProps>(
  function DialogContent(
    { initialFocusRef, onEscapeKeyDown, tabIndex = -1, ...props },
    forwardedRef,
  ) {
    const context = useDialogContext('Dialog.Content')
    const surfaceRef = useRef<HTMLDivElement | null>(null)
    const ref = useComposedRefs(forwardedRef, surfaceRef)
    const escapeHandlerRef = useLatest(onEscapeKeyDown)
    const explicitLabelledBy = props['aria-labelledby']
    const explicitDescribedBy = props['aria-describedby']
    const hasExplicitLabel = Boolean(props['aria-label'])
    const labelledBy = explicitLabelledBy ?? (hasExplicitLabel ? undefined : context.titleMounted ? context.titleId : undefined)
    const describedBy = explicitDescribedBy ?? (context.descriptionMounted ? context.descriptionId : undefined)

    useBrowserLayoutEffect(() => {
      const surface = surfaceRef.current
      if (!surface || !context.open) return
      const document = surface.ownerDocument
      const window = document.defaultView
      const previousFocus = context.returnFocusRef.current ?? (
        document.activeElement instanceof HTMLElement ? document.activeElement : null
      )
      context.returnFocusRef.current = null

      if (context.restoreAnimationFrameRef.current !== null && window) {
        window.cancelAnimationFrame(context.restoreAnimationFrameRef.current)
        context.restoreAnimationFrameRef.current = null
      }

      const unregisterLayer = registerDialogLayer(document, {
        id: context.layerId,
        surface,
      })

      focusInitialElement(surface, initialFocusRef?.current)

      const handleKeyDown = (event: KeyboardEvent) => {
        if (!isTopDialogLayer(document, context.layerId)) return

        if (event.key === 'Escape') {
          escapeHandlerRef.current?.(event)
          if (event.defaultPrevented) return
          event.preventDefault()
          event.stopImmediatePropagation()
          context.requestOpenChange(false)
        } else if (event.key === 'Tab' && !event.defaultPrevented) {
          containTabFocus(event, surface)
        }
      }

      const handleFocusIn = (event: FocusEvent) => {
        if (
          isTopDialogLayer(document, context.layerId) &&
          event.target instanceof Node &&
          !surface.contains(event.target)
        ) focusInitialElement(surface, initialFocusRef?.current)
      }

      document.addEventListener('keydown', handleKeyDown)
      document.addEventListener('focusin', handleFocusIn, true)

      return () => {
        document.removeEventListener('keydown', handleKeyDown)
        document.removeEventListener('focusin', handleFocusIn, true)
        unregisterLayer()

        if (!previousFocus?.isConnected || !window) return
        context.restoreAnimationFrameRef.current = window.requestAnimationFrame(() => {
          context.restoreAnimationFrameRef.current = null
          if (previousFocus.isConnected) previousFocus.focus({ preventScroll: true })
        })
      }
    }, [
      context.layerId,
      context.open,
      context.requestOpenChange,
      context.restoreAnimationFrameRef,
      context.returnFocusRef,
      escapeHandlerRef,
      initialFocusRef,
    ])

    return (
      <div
        {...props}
        aria-describedby={describedBy}
        aria-labelledby={labelledBy}
        aria-modal="true"
        data-state={context.open ? 'open' : 'closed'}
        id={context.contentId}
        ref={ref}
        role="dialog"
        tabIndex={tabIndex}
      />
    )
  },
)

export const DialogTitle = forwardRef<HTMLHeadingElement, DialogTitleProps>(
  function DialogTitle(props, forwardedRef) {
    const context = useDialogContext('Dialog.Title')
    useBrowserLayoutEffect(() => context.registerTitle(), [context.registerTitle])
    return <h2 {...props} id={context.titleId} ref={forwardedRef} />
  },
)

export const DialogDescription = forwardRef<HTMLParagraphElement, DialogDescriptionProps>(
  function DialogDescription(props, forwardedRef) {
    const context = useDialogContext('Dialog.Description')
    useBrowserLayoutEffect(() => context.registerDescription(), [context.registerDescription])
    return <p {...props} id={context.descriptionId} ref={forwardedRef} />
  },
)

export const DialogClose = forwardRef<HTMLButtonElement, DialogCloseProps>(
  function DialogClose({ onClick, type = 'button', ...props }, forwardedRef) {
    const context = useDialogContext('Dialog.Close')
    return (
      <button
        {...props}
        onClick={(event) => {
          onClick?.(event)
          if (!event.defaultPrevented) context.requestOpenChange(false)
        }}
        ref={forwardedRef}
        type={type}
      />
    )
  },
)

export const Dialog = {
  Close: DialogClose,
  Content: DialogContent,
  Description: DialogDescription,
  Overlay: DialogOverlay,
  Portal: DialogPortal,
  Root: DialogRoot,
  Title: DialogTitle,
  Trigger: DialogTrigger,
} as const

const focusableSelector = [
  'a[href]',
  'area[href]',
  'button:not([disabled])',
  'input:not([disabled]):not([type="hidden"])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  'iframe',
  'object',
  'embed',
  '[contenteditable="true"]',
  '[tabindex]',
].join(',')

function isFocusable(element: HTMLElement) {
  if (element.tabIndex < 0 || element.closest('[inert]')) return false

  const style = element.ownerDocument.defaultView?.getComputedStyle(element)
  return style?.display !== 'none' && style?.visibility !== 'hidden' && element.getClientRects().length > 0
}

export function getTabbableElements(container: HTMLElement) {
  return Array.from(container.querySelectorAll<HTMLElement>(focusableSelector))
    .filter(isFocusable)
    .map((element, documentOrder) => ({ documentOrder, element, tabIndex: element.tabIndex }))
    .sort((left, right) => {
      const leftOrder = left.tabIndex === 0 ? Number.MAX_SAFE_INTEGER : left.tabIndex
      const rightOrder = right.tabIndex === 0 ? Number.MAX_SAFE_INTEGER : right.tabIndex
      return leftOrder - rightOrder || left.documentOrder - right.documentOrder
    })
    .map(({ element }) => element)
}

export function focusInitialElement(container: HTMLElement, preferred?: HTMLElement | null) {
  const target = preferred && container.contains(preferred) && isFocusable(preferred)
    ? preferred
    : getTabbableElements(container)[0] ?? container

  target.focus({ preventScroll: true })
}

export function containTabFocus(event: KeyboardEvent, container: HTMLElement) {
  const tabbable = getTabbableElements(container)

  if (tabbable.length === 0) {
    event.preventDefault()
    container.focus({ preventScroll: true })
    return
  }

  const first = tabbable[0]
  const last = tabbable[tabbable.length - 1]
  const active = container.ownerDocument.activeElement

  if (event.shiftKey && (active === first || !container.contains(active))) {
    event.preventDefault()
    last.focus({ preventScroll: true })
  } else if (!event.shiftKey && (active === last || !container.contains(active))) {
    event.preventDefault()
    first.focus({ preventScroll: true })
  }
}

type DialogLayer = {
  id: symbol
  surface: HTMLElement
}

const layersByDocument = new WeakMap<Document, DialogLayer[]>()

function updateLayerAccessibility(layers: DialogLayer[]) {
  const topLayer = layers.at(-1)

  for (const layer of layers) {
    const isTopLayer = layer === topLayer
    layer.surface.toggleAttribute('inert', !isTopLayer)
    if (isTopLayer) layer.surface.removeAttribute('aria-hidden')
    else layer.surface.setAttribute('aria-hidden', 'true')
  }
}

export function registerDialogLayer(document: Document, layer: DialogLayer) {
  const layers = layersByDocument.get(document) ?? []
  layers.push(layer)
  layersByDocument.set(document, layers)
  updateLayerAccessibility(layers)

  return () => {
    const index = layers.indexOf(layer)
    if (index !== -1) layers.splice(index, 1)
    layer.surface.removeAttribute('inert')
    layer.surface.removeAttribute('aria-hidden')
    updateLayerAccessibility(layers)
    if (layers.length === 0) layersByDocument.delete(document)
  }
}

export function isTopDialogLayer(document: Document, id: symbol) {
  return layersByDocument.get(document)?.at(-1)?.id === id
}

